  name: "LineChartShort",
  props: {
    chartData: {
      type: Array,
      default: () => [],
    },
    alarmTotal: {
      type: Number,
      default: 0,
    },
    colorStops: {
      type: Array,
      default: () => [],
    },
  },
  data() {
    return {
      chartInstance: null,
      rawLegendData: [
        "Human Experts",
        "Gemini-1.5-Pro-002",
        "GPT-4o",
        "Gemini-1.5-Flash-002",
        "Qwen-VL-Max",
        "Gemini-1.5-Flash-8B",
        "LongVU-7B",
        "E.T. Chat-3.8B",
