        "VILA1.5-40B",
        "MiniCPM v2.6-8B",
        "Oryx-34B",
        "VILA1.5-13B",
        "LongVA-7B",
        "LLaVA-Video-7B",
        "AoTD",
        "Video-RAG",
        "Moment-DETR",
        "UniVTG",
        "Time-R1-3B",
        "Time-R1-7B",
        "Qwen2.5-VL-7B",
        "Qwen2.5-VL-72B",
      ],
      rawSeriesData: [
        [93.62, 96.1, 95.31, 94.33, 95.39, 96.31, 93.98],
        [65.83, 78.22, 89.81, 74.85, 85.54, 92.85, 70.34],
        [64.07, 74.85, 88.56, 71.41, 81.18, 89.91, 67.74],
        [62.64, 73.73, 85.24, 72.1, 81.26, 90.15, 67.37],
        [54.46, 63.69, 82.77, 56.63, 64.8, 83.03, 55.55],
        [41.86, 50.85, 73.89, 55.7, 63.44, 82.38, 48.78],
        [15.37, 31.44, 63.06, 19.43, 34.18, 68.48, 17.4],
        [9.72, 21.54, 38.23, 14.94, 26.82, 45.56, 12.33],
        [8.88, 18.36, 40.4, 12.31, 22.08, 41.89, 10.6],
        [4.49, 10.88, 27.5, 6.82, 16.68, 40.84, 5.66],
        [4.49, 10.68, 36.94, 3.87, 12.61, 41.75, 4.18],
        [2.69, 8.88, 34.95, 5.39, 13.84, 41.4, 4.04],
        [0.8, 1.9, 4.72, 3.36, 6.21, 14.77, 2.08],
        [1.2, 4.49, 18.19, 2.54, 6.51, 21.87, 1.87],
        [1.1, 1.9, 11.27, 2.34, 4.07, 19.48, 1.72],
        [2.79, 5.29, 14.69, 3.36, 6.1, 11.95, 3.08],
        [0.3, 1.1, 7.52, 0.71, 1.83, 12.14, 0.51],
        [7.09, 17.17, 40.78, 10.38, 23.19, 51.2, 8.74],
        [13.0, 24.7, 53.16, 19.65, 34.42, 64.19, 16.33],
        [15.27, 32.53, 63.84, 22.38, 40.18, 72.85, 18.82],
        [22.36, 38.02, 68.25, 29.79, 44.86, 74.76, 26.03],
        [24.45, 32.63, 57.22, 29.7, 41.71, 65.62, 27.08],
        [28.04, 37.62, 61.01, 31.11, 43.13, 66.66, 29.69],
      ],

      rawColors: [
        "#FF5F5F",
        "#9E7CFF",
        "#40C4FF",
        "#69F0AE",
        "#FFF153",
        "#FF764B",
        "#EE88FF",
        "#279BCF",
        "#9CCC65",
        "#AEE5FF",
        "#FFA8B3",
        "#FFD700",
        "#FF69B4",
        "#8A2BE2",
        "#FF4500",
        "#2E8B57",
      ],
      checkedLegends: [],
    };
  },
  computed: {
    /* 1. 按 Avg 降序取前 16 个模型 */
    sortedTop16() {
      return this.rawSeriesData
        .map((d, idx) => ({ idx, avg: d[6] }))
        .sort((a, b) => b.avg - a.avg)
        .slice(0, 16);
    },
    /* 2. 仅 16 种颜色，且与排序后顺序一一对应 */
    top16Colors() {
      const base16 = this.rawColors.slice(0, 16);
      return this.sortedTop16.map((_, i) => base16[i]);
    },
    top16Legend() {
      return this.sortedTop16.map((item) => this.rawLegendData[item.idx]);
    },
    top16Series() {
      return this.sortedTop16.map((item) => this.rawSeriesData[item.idx]);
    },
    /* 3. 构造 modelColors 映射（排序后模型名 -> 上面 16 色） */
    modelColors() {
      const map = {};
      this.top16Legend.forEach((name, i) => {
        map[name] = this.top16Colors[i];
      });
      return map;
    },
  },
  watch: {
    chartData: {
      deep: true,
      handler() {
        this.$nextTick(() => {
          this.updateChart();
        });
      },
    },
    // 监听窗口 resize，适配图表尺寸
    "$refs.LineChartShort.offsetWidth": {
      handler() {
        this.resizeChart();
      },
      immediate: false,
    },
  },
  mounted() {
    this.initChart();
    this.checkedLegends = [...this.top16Legend];
    this.updateChart();
    window.addEventListener("resize", this.resizeChart);
  },
  beforeDestroy() {
    window.removeEventListener("resize", this.resizeChart);
    if (this.chartInstance) {
      this.chartInstance.dispose();
      this.chartInstance = null;
    }
  },
  methods: {
    initChart() {
      this.chartInstance = this.$echarts.init(this.$refs.LineChartShort);
    },
    updateChart() {
      const option = this.chartOption();
      // 强制更新，避免缓存问题
      this.chartInstance.setOption(option, true);
    },
    resizeChart() {
      if (this.chartInstance) {
        this.chartInstance.resize();
      }
    },
    chartOption() {
      const visibleSeries = this.top16Legend.reduce((acc, name) => {
        if (this.checkedLegends.includes(name)) {
          const dataIdx = this.top16Legend.indexOf(name);
          acc.push({
            name,
            type: "bar",
            data: this.top16Series[dataIdx],
            color: this.modelColors[name],
            barWidth: 6,
            barGap: 0.2,
          });
        }
        return acc;
      }, []);

      return {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow",
          },
          textStyle: {
            lineHeight: 18,
            fontSize: 12, // 适配小屏幕文字大小
          },
          confine: true, // 限制tooltip在图表内显示
          padding: 8, // 减少内边距，节省空间
        },
        legend: {
          show: false,
        },
        grid: {
          left: "10%",
          right: "3%",
          bottom: "50px", // 增加底部间距，避免x轴标签被遮挡
          top: "5%",
          containLabel: false,
        },
        xAxis: [
          {
            type: "category",
            data: [
              "Object Recall@1x, tIoU=0.7",
              "Object Recall@1x, tIoU=0.5",
              "Object Average mAP",
              "Scene Recall@1x, tIoU=0.7",
              "Scene Recall@1x, tIoU=0.5",
              "Scene Average mAP",
              "Avg Recall@1x, tIoU=0.7",
            ],
            axisLine: {
              show: false,
            },
            axisTick: {
              show: false,
            },
            axisLabel: {
              show: true,
              textStyle: {
                color: "#E0E0E0",
                fontSize: 11, // 适配小屏幕标签文字
              },
              interval: 0,
              rotate: 15, // 轻微旋转x轴标签，避免重叠
            },
          },
        ],
        yAxis: [
          {
            type: "value",
            axisLabel: {
              formatter: "{value}",
              textStyle: {
                color: "#E0E0E0",
                fontSize: 11, // 适配小屏幕数值文字
              },
            },
            axisTick: {
              show: false,
            },
            axisLine: {
              show: false,
              lineStyle: {
                color: "#E0E0E0",
                width: 1,
                type: "solid",
              },
            },
            splitLine: {
              lineStyle: {
                color: "#7A7A7A",
              },
            },
          },
        ],
        series: visibleSeries,
      };
    },
    handleLegendChange() {
      this.updateChart();
    },
  },
};
</script>

